import React from 'react';

import nophoto from '../../img/nophoto.png';
import PohIcon from '../Icon';
import IconsEnum from '../Icon/IconsEnum';

interface IPohImagePlaceholderProps extends React.HTMLAttributes<HTMLImageElement> {
  src: string;
  alt: string;
  iconName?: IconsEnum;
}

const PohImagePlaceholder = ({
  src,
  alt,
  iconName,
  ...anotherProps
}: IPohImagePlaceholderProps) => {
  const [hasErr, setHasErr] = React.useState(!src);

  if (hasErr) {
    if (iconName) {
      return (
        <PohIcon
          name={iconName}
          style={{ width: 'auto', height: 'auto', fill: '#adadad' }}
          {...anotherProps}
        />
      );
    }

    return <img src={nophoto} alt={alt} {...anotherProps} />;
  }

  return (
    <img
      src={src}
      alt={alt}
      onError={() => {
        setHasErr(true);
      }}
      {...anotherProps}
    />
  );
};

export default PohImagePlaceholder;
